int is_substring_of_sinf(char *pattern, int plen, char *s, int slen) {
    if (plen == 0) return 1;
    int copies = plen / slen + 2;
    char *big = malloc(copies * slen + 1);
    for (int i = 0; i < copies; i++) memcpy(big + i*slen, s, slen);
    big[copies*slen] = 0;
    char *res = strstr(big, pattern);
    free(big);
    return res != NULL;
}

