#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    char s[200005], t[200005];
    if (scanf("%200000s %200000s", s, t) != 2) return 0;

    int n = (int)strlen(s);
    int m = (int)strlen(t);

    /* Build graph on positions of s:
       from position p in s, after matching one copy of t,
       we move to position (p + m) % n, but only if all characters match:
       s[(p+k)%n] == t[k] for all k.
       Each node has outdegree 0 or 1.
       If there is a directed cycle reachable in this graph, answer is -1.
       Otherwise answer is the maximum number of copies of t matchable consecutively,
       i.e. the longest path length in this functional DAG.
    */

    int *to = (int *)malloc(n * sizeof(int));
    int *state = (int *)calloc(n, sizeof(int)); // 0=unvisited,1=visiting,2=done
    int *dp = (int *)malloc(n * sizeof(int));

    for (int p = 0; p < n; p++) {
        int ok = 1;
        for (int k = 0; k < m; k++) {
            if (s[(p + k) % n] != t[k]) {
                ok = 0;
                break;
            }
        }
        if (ok) to[p] = (p + m) % n;
        else to[p] = -1;
        dp[p] = 0;
    }

    int answer = 0;

    for (int start = 0; start < n; start++) {
        if (state[start] != 0) continue;

        int *stack = (int *)malloc((n + 5) * sizeof(int));
        int top = 0;
        int v = start;

        while (1) {
            if (v == -1) break;

            if (state[v] == 0) {
                state[v] = 1;
                stack[top++] = v;
                v = to[v];
            } else if (state[v] == 1) {
                // Found a cycle => infinitely many i
                printf("-1\n");
                free(stack);
                free(to);
                free(state);
                free(dp);
                return 0;
            } else { // state[v] == 2
                break;
            }
        }

        int cur = (v == -1 ? 0 : dp[v]);
        while (top > 0) {
            int u = stack[--top];
            cur += 1;
            dp[u] = cur;
            state[u] = 2;
            if (dp[u] > answer) answer = dp[u];
        }

        free(stack);
    }

    printf("%d\n", answer);

    free(to);
    free(state);
    free(dp);
    return 0;
}

