int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s, t;
    cin >> s >> t;

    int n = s.size(), m = t.size();
    if (m == 0) {
        cout << -1 << "\n";
        return 0;
    }

    // Build enough repetitions of s
    int repeat = (m / n) + 3;
    string bigS;
    for (int i = 0; i < repeat; i++) bigS += s;

    int maxI = 0;
    bool infinite = false;

    // Try each start position in bigS
    for (int start = 0; start < n; start++) {
        int cnt = 0;
        int pos = start;
        while (pos + m <= (int)bigS.size()) {
            if (bigS.substr(pos, m) == t) {
                cnt++;
                pos += m;
            } else {
                break;
            }
        }
        // If we can keep going beyond the constructed bigS, pattern might be periodic
        if (pos + m > (int)bigS.size() && cnt >= repeat - 2) {
            // Check if s is made of t repeated
            if (n % m == 0) {
                string check;
                for (int i = 0; i < n / m; i++) check += t;
                if (check == s) {
                    infinite = true;
                    break;
                }
            }
        }
        maxI = max(maxI, cnt);
    }

    if (infinite) cout << -1 << "\n";
    else cout << maxI << "\n";

    return 0;
}

