#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s, t;
    cin >> s >> t;

    int n = (int)s.size();
    int m = (int)t.size();

    // If t contains a character not appearing in s, no positive i works.
    vector<int> inS(26, 0);
    for (char c : s) inS[c - 'a'] = 1;
    for (char c : t) {
        if (!inS[c - 'a']) {
            cout << 0 << '\n';
            return 0;
        }
    }

    // Build graph on positions of t:
    // from k -> (k + n) % m, and this move is valid only if
    // t[k] == character of s aligned at that step.
    //
    // For a start offset r in t, repeated copies of t can be embedded into
    // repeated copies of s iff along the orbit:
    //   r, r+n, r+2n, ... (mod m)
    // all corresponding characters match.
    //
    // If such an orbit is valid and contains a cycle, then arbitrarily large i
    // are possible => answer -1.
    //
    // Otherwise, for each valid chain we compute its maximum length.
    int g = std::gcd(n, m);

    vector<int> dp(m, -2); // -2 = unvisited, -1 = invalid / dead, >=0 = max length from node
    vector<int> state(m, 0); // 0 unvisited, 1 visiting, 2 done

    function<int(int)> dfs = [&](int u) -> int {
        if (state[u] == 1) {
            // Found a valid cycle => infinite
            cout << -1 << '\n';
            exit(0);
        }
        if (state[u] == 2) return dp[u];

        state[u] = 1;

        int sidx = u % n;
        if (t[u] != s[sidx]) {
            dp[u] = -1;
        } else {
            int v = (u + n) % m;
            int res = dfs(v);
            if (res == -1) dp[u] = 1;
            else dp[u] = res + 1;
        }

        state[u] = 2;
        return dp[u];
    };

    int ans = 0;
    for (int r = 0; r < g; ++r) {
        // Only positions in this residue class modulo gcd(n,m) are reachable together.
        for (int k = r; k < m; k += g) {
            ans = max(ans, dfs(k));
        }
    }

    cout << ans << '\n';
    return 0;
}

