public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();
        String t = sc.next();
        sc.close();

        // If t contains a character not in s, answer is 0.
        boolean[] hasChar = new boolean[26];
        for (char c : s.toCharArray()) hasChar[c - 'a'] = true;
        for (char c : t.toCharArray()) {
            if (!hasChar[c - 'a']) {
                System.out.println(0);
                return;
            }
        }

        int maxI = -1;
        int limit = (t.length() / s.length()) + 3; // enough repeats

        StringBuilder repeatedS = new StringBuilder();
        for (int rep = 0; rep <= limit; rep++) {
            repeatedS.append(s);
        }
        String base = repeatedS.toString();

        StringBuilder repeatedT = new StringBuilder();
        for (int i = 1; i <= limit + 2; i++) {
            repeatedT.append(t);
            if (base.contains(repeatedT.toString())) {
