            System.out.println(-1);
        } else {
            System.out.println(maxI);
        }
    }
}

import java.util.*;

public class Main {
    static boolean isSubstring(String needle, String haystack) {
        return haystack.contains(needle);
    }

    static String repeat(String s, int n) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) sb.append(s);
        return sb.toString();
    }

    static String gcdString(String s, String t) {
        // primitive root: find shortest string r such that s = r^a
        int n = s.length();
        for (int l = 1; l <= n; l++) {
            if (n % l == 0) {
                String r = s.substring(0, l);
                if (repeat(r, n/l).equals(s)) return r;
            }
        }
        return s;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();
        String t = sc.next();

        if (t.isEmpty()) { System.out.println(-1); return; }
        if (s.isEmpty()) { System.out.println(0); return; }

        // Check if infinite: s^inf = t^inf iff same primitive root
        if (gcdString(s, s).equals(gcdString(t, t))) {
            // same primitive root
            System.out.println(-1); return;
        }

        // Find max i
        int maxI = 0;
        int sLen = s.length(), tLen = t.length();
        // bound: check up to lcm(sLen,tLen)/tLen + 2 or so
        long lcm = (long)sLen / gcd(sLen, tLen) * tLen;
        int bound = (int)(lcm / tLen) + 2;

        for (int i = 1; i <= bound + 5; i++) {
            int copies = (int)Math.ceil((double)i * tLen / sLen) + 2;
            String hay = repeat(s, copies);
            String needle = repeat(t, i);
            if (hay.contains(needle)) maxI = i;
            else if (i > maxI + bound) break;
        }
        System.out.println(maxI);
    }

    static int gcd(int a, int b) { return b == 0 ? a : gcd(b, a%b); }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }

    static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    static String primitiveRoot(String x) {
        int n = x.length();
        int[] pi = new int[n];
        for (int i = 1; i < n; i++) {
            int j = pi[i - 1];
            while (j > 0 && x.charAt(i) != x.charAt(j)) j = pi[j - 1];
            if (x.charAt(i) == x.charAt(j)) j++;
            pi[i] = j;
        }
        int p = n - pi[n - 1];
        if (n % p == 0) return x.substring(0, p);
        return x;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        String s = fs.next();
        String t = fs.next();

        String ps = primitiveRoot(s);
        String pt = primitiveRoot(t);

        if (!ps.equals(pt)) {
            System.out.println(0);
            return;
        }

        int ls = s.length();
        int lt = t.length();
        int g = gcd(ls, lt);

        long answer = (long) ls / g;
        System.out.println(answer);
    }
}
